package com.example.starter.batch.dto;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 复检延期提交请求。extensionKey 为批次内唯一的延期业务键（最多生效一次）；
 * retestConclusion 为本次复检结论，PASS=合格/FAIL=不合格，仅合格允许提交；
 * extensionMinutes 为本次顺延分钟，1～43200。
 */
public record SubmitExtensionRequest(
        @NotBlank(message = "commandKey 不能为空") String commandKey,
        @NotBlank(message = "extensionKey 不能为空") String extensionKey,
        @NotBlank(message = "retestConclusion 不能为空") String retestConclusion,
        @NotNull(message = "extensionMinutes 不能为空")
        @Min(value = 1, message = "extensionMinutes 必须在 1～43200 之间")
        @Max(value = 43200, message = "extensionMinutes 必须在 1～43200 之间")
        Integer extensionMinutes
) {
}

package com.example.starter.batch.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 延期确认请求。确认人由 X-Actor-Id 给出，须为不同于复检人的批准角色（X-Approval-Role）。
 */
public record ConfirmExtensionRequest(
        @NotBlank(message = "commandKey 不能为空") String commandKey
) {
}

package com.example.starter.batch.dto;

import java.time.Instant;

/**
 * 延期记录响应。status 为 PENDING_CONFIRM（待确认）或 EFFECTIVE（已生效，终态不可改写）；
 * confirmedBy/confirmedRole/confirmedAt/newExpiresAt 仅在生效后有值。
 */
public record ExtensionResponse(
        String batchKey,
        String extensionKey,
        String retestConclusion,
        int extensionMinutes,
        String retester,
        String status,
        Instant submittedAt,
        String confirmedBy,
        String confirmedRole,
        Instant confirmedAt,
        Instant newExpiresAt
) {
}

package com.example.starter.batch.dto;

import java.time.Instant;

/**
 * 批次有效期查询响应。remainingMinutes 为查询时刻距有效期截止的整分钟数，到期后为负数；
 * expired 为查询时刻是否已到期；cumulativeExtendedMinutes 为已生效延期累计顺延分钟；
 * effectiveExtensions 为已生效延期次数（上限 3 次，累计顺延不超过原保质分钟两倍）。
 */
public record ShelfLifeResponse(
        String batchKey,
        int shelfLifeMinutes,
        Instant producedAt,
        Instant expiresAt,
        long remainingMinutes,
        boolean expired,
        int cumulativeExtendedMinutes,
        int effectiveExtensions
) {
}

package com.example.starter.batch.dto;

import com.example.starter.batch.BatchStatus;

import java.time.Instant;

/**
 * 到期批次清单项。expired 标识不影响批次状态本身，状态原样返回。
 */
public record ExpiredBatchResponse(
        String batchKey,
        String productCode,
        String batchNo,
        BatchStatus status,
        Instant expiresAt
) {
}

