public StoredResponse submitExtension(String batchKey, String actorId, SubmitExtensionRequest req) {
    if (actorId == null || actorId.isBlank()) throw badRequest("X-Actor-Id 不能为空");
    String retester = actorId.trim();
    String conclusion = req.retestConclusion().trim();
    String fingerprint = fingerprint("ext-submit", batchKey, req.extensionKey(), conclusion,
            req.extensionMinutes().toString(), retester);
    return executeIdempotent(CMD_EXTENSION_SUBMIT, req.commandKey(), fingerprint, () -> {
        BatchRow batch = repo.findBatchForUpdate(batchKey).orElseThrow(notFound);
        var logged = loggedResponse(CMD_EXTENSION_SUBMIT, req.commandKey(), fingerprint);
        if (logged.isPresent()) return logged.get();
        assertNoRecalledAncestor(batchKey); // 422
        if (repo.findExtension(batchKey, req.extensionKey()).isPresent())
            throw conflict("extensionKey 已存在...");
        List<String> required = repo.findRequiredTests(batchKey);
        if (!allRequiredPassed(batchKey, required))
            throw unprocessable("必做检验项未全部通过，不能提交延期");
        if (!"PASS".equals(conclusion))
            throw unprocessable("本次复检结论为不合格，不能提交延期");
        boolean retesterApproved = repo.findApprovals(batchKey).stream()
                .anyMatch(a -> a.actorId().equals(retester));
        if (retesterApproved) throw unprocessable("复检人须与该批次原批准人都不同: " + retester);
        assertExtensionLimits(batch, req.extensionMinutes());
        String now = now();
        repo.insertExtension(new ExtensionRow(0L, batchKey, req.extensionKey(), conclusion,
                req.extensionMinutes(), retester, "PENDING_CONFIRM", now, null, null, null));
        ExtensionResponse body = new ExtensionResponse(batchKey, req.extensionKey(), conclusion,
                req.extensionMinutes(), retester, "PENDING_CONFIRM", Instant.parse(now),
                null, null, null, null);
        return new StoredResponse(201, toJson(body));
    });
}
```

assertExtensionLimits(batch, additionalMinutes):
```java
List<ExtensionRow> effective = repo.findExtensions(batch.batchKey()).stream()
        .filter(e -> "EFFECTIVE".equals(e.status())).toList();
if (effective.size() >= 3) throw unprocessable("延期次数已达上限 3 次");
long cumulative = effective.stream().mapToLong(ExtensionRow::extensionMinutes).sum();
if (cumulative + additionalMinutes > 2L * batch.shelfLifeMinutes())
    throw unprocessable("累计顺延分钟超过原保质分钟两倍上限");
```

