public StoredResponse confirmExtension(String batchKey, String extensionKey, String actorId,
                                       String roleHeader, ConfirmExtensionRequest req) {
    if (actorId == null || actorId.isBlank()) throw badRequest;
    ApprovalRole role = parseRole(roleHeader);
    String confirmer = actorId.trim();
    String fingerprint = fingerprint("ext-confirm", batchKey, extensionKey, confirmer, role.name());
    return executeIdempotent(CMD_EXTENSION_CONFIRM, req.commandKey(), fingerprint, () -> {
        BatchRow batch = repo.findBatchForUpdate(batchKey).orElseThrow(notFound);
        var logged = loggedResponse(...); if present return;
        ExtensionRow ext = repo.findExtension(batchKey, extensionKey)
                .orElseThrow(() -> ApiException.notFound("延期不存在: " + extensionKey));
        if ("EFFECTIVE".equals(ext.status())) throw conflict("延期已生效，不可重复确认");
        if (ext.retester().equals(confirmer)) throw unprocessable("确认人须不同于复检人");
        assertNoRecalledAncestor(batchKey);
        List<String> required = repo.findRequiredTests(batchKey);
        if (!allRequiredPassed(batchKey, required)) throw unprocessable(...);
        assertExtensionLimits(batch, ext.extensionMinutes());
        String now = now();
        repo.markExtensionEffective(batchKey, extensionKey, confirmer, role.name(), now);
        String newExpiresAt = canonical(Instant.parse(batch.expiresAt())
                .plusSeconds(ext.extensionMinutes() * 60L));
        repo.updateExpiresAt(batchKey, newExpiresAt);
        ExtensionResponse body = new ExtensionResponse(batchKey, extensionKey, ext.retestConclusion(),
                ext.extensionMinutes(), ext.retester(), "EFFECTIVE", Instant.parse(ext.submittedAt()),
                confirmer, role.name(), Instant.parse(now), Instant.parse(newExpiresAt));
        return new StoredResponse(200, toJson(body));
    });
}
